import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.Reader;
import java.io.StreamTokenizer;
import java.io.Writer;

public class Main {

    static final int INF = 1000000001;

    static class Pair {
        int first, second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static int[] sort(int[] arr) {
        sort(arr, 0, arr.length);
        return arr;
    }

    static void sort(int[] arr, int from, int to) {
        int n = to - from;
        if (n < 2) {
            return;
        }
        int left = from;
        int right = to - 1;
        int pivot = from + n / 2;

        int tmp = arr[pivot];
        arr[pivot] = arr[right];
        arr[right] = tmp;

        for (int i = from; i < to; i++) {
            if (arr[i] < arr[right]) {
                tmp = arr[i];
                arr[i] = arr[left];
                arr[left] = tmp;
                left++;
            }
        }

        tmp = arr[left];
        arr[left] = arr[right];
        arr[right] = tmp;

        sort(arr, from, left);
        sort(arr, left + 1, to);
    }

    static boolean check(int n) {
        int s = 0;
        while (n > 0) {
            s += n % 10;
            n /= 10;
        }
        return s == 10;
    }

    static void solution(Reader reader, Writer writer) throws IOException {
        StreamTokenizer in = new StreamTokenizer(reader);
        in.nextToken();
        int k = (int) in.nval;
        for (int i = 19; k > 0; i++) {
            if (check(i)) {
                k--;
            }
            if (k == 0) {
                System.out.println(i);
                return;
            }
        }
    }

    public static void main(String[] args) throws IOException {

        //InputStream stdin = new FileInputStream("file.in");
        InputStream stdin = System.in;
        BufferedReader reader = new BufferedReader(new InputStreamReader(stdin), 1024 * 1024);

        //OutputStream stdout = new FileOutputStream("file.out");
        OutputStream stdout = System.out;
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(stdout), 1024 * 1024);

        try {
            solution(reader, writer);
        } finally {
            writer.flush();
        }
    }
}
